create table maintenance_bills (base_amount numeric(12,2) not null, due_date date not null, paid_amount numeric(12,2), penalty_amount numeric(12,2), apartment_id bigint not null, billing_template_id bigint, flat_id bigint not null, generated_at timestamp(6), id bigint generated by default as identity, paid_at timestamp(6), status varchar(255) not null check ((status in ('UNPAID','PARTIALLY_PAID','PAID','OVERDUE'))), title varchar(255) not null, primary key (id));
alter table if exists maintenance_bills add constraint FK6f1iwyn1jv1kjnp5j277j0ywa foreign key (apartment_id) references apartments;
alter table if exists maintenance_bills add constraint FK42wj889jm6mh6euflx7fjd37f foreign key (billing_template_id) references billing_templates;
alter table if exists maintenance_bills add constraint FKl5aqkn3dbmy530jya3xwwhhi3 foreign key (flat_id) references flats;
